M23:bg:spectrum.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/background.tex:68-78; theorem: Weighted homogeneous spectrum] \label{bg:spectrum}
If $f$ is weighted homogeneous of normalized degree $1$ and has an isolated
critical point, its spectral polynomial is
\begin{equation}\label{eq:bg-spectrum}
 P_f(t)=\sum_{\beta\in\operatorname{Sp}^{+}(f)}t^\beta
       =\prod_{j=1}^s\frac{t^{w_j}-t}{1-t^{w_j}}.
\end{equation}
Exponents are counted with multiplicity.  Their classes modulo $\mathbb Z$
determine the eigenvalues of $M_f$ by exponentiation, with a fixed choice
of sign in the exponent.  The operator $M_f$ has finite order.

M23:topo:sphere.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/conclusion.tex:117-121; lemma] \label{topo:sphere}
Each $K_j$ is a homotopy sphere, and each embedding
$K_j\subset S^{2n+1}_\varepsilon$ is a simple knot.

M23:topo:seifert.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/conclusion.tex:58-64; equation] \label{topo:seifert}
 \Psi^{\mathsf t}S_2^{\mathrm f}\Psi
 =\Psi^{\mathsf t}B_2^{\mathrm f}(T_2^{\mathrm f})^{-r}\Psi
 =B_1^{\mathrm f}(T_1^{\mathrm f})^{-r}
 =S_1^{\mathrm f}.

M23:thm:main.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/introduction.tex:39-51; theorem] \label{thm:main}
There is a finite integer $N>3$, divisible by eight, and there are reduced
polynomials $f_1,f_2\in\R[z_1,\ldots,z_N]$, weighted homogeneous for
positive rational weights, such that:
\begin{enumerate}[label=\textup{(\roman*)}]
\item each $f_j$ has an isolated critical point at the origin;
\item $\ord_0f_1=2$ and $\ord_0f_2=3$;
\item there is a homeomorphism germ of ambient pairs
\[
 (\C^N,V(f_1),0)\ \cong\ (\C^N,V(f_2),0).
\]
\end{enumerate}

M23:local:lifting.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/local.tex:68-79; lemma: Lifting in a finite operator algebra] \label{local:lifting}
Let $\ell$ be an odd prime and let $\mathcal A$ be a commutative
$\Z_\ell$-algebra that is finite as a $\Z_\ell$-module.  Write $J$ for
its Jacobson radical.  Then $\mathcal A/J$ is a product of finite fields,
and $\mathcal A$ is complete for the $J$-adic topology.  For a unit
$u\in\mathcal A$:
\begin{enumerate}
\item if its image in every residue field is a square, then $u$ is a
square in $\mathcal A$;
\item $u=a^2+b^2$ for some $a,b\in\mathcal A$.
\end{enumerate}

M23:seed:product.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/seeds.tex:7-20; lemma: Finite product relation] \label{seed:product}
Set $d=3^{11}$ and
\[
 \mathcal B=\{b\in\Z:0<b<d/2,\ 3\nmid b\},\qquad
 A_b=\frac{d-b}{b},\qquad
 R_b=\frac{(2d+b)(2d-b)}{(3d-b)(d+b)}.
\]
There are integers $e_b$, $b\in\mathcal B$, such that
\begin{equation}\label{seed:products}
 E:=\sum_{b\in\mathcal B}e_b>0,
 \qquad \prod_{b\in\mathcal B}A_b^{e_b}
 =\prod_{b\in\mathcal B}R_b^{e_b}=1.
\end{equation}

M23:seed:chain.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/seeds.tex:78-91; lemma: Completing one weight to a chain] \label{seed:chain}
Let $D$ be a positive odd integer and let $c\in\Z$ satisfy
$0<c<D/2$.  There is a chain
polynomial
\begin{equation}\label{seed:chain-polynomial}
 F_c=x_1^{a_1}x_2+\cdots+x_{\ell-1}^{a_{\ell-1}}x_\ell
       +x_\ell^{a_\ell}
\end{equation}
of weighted degree $1$, whose first weight is $c/D$, all of whose
weights are positive and less than $1/2$, and all of whose ordinary
monomial degrees are at least $3$.  It has an isolated critical point
at the origin.  Removing its first variable and first monomial gives
a chain with exactly the remaining weights, when $\ell>1$.

M23:seed:seeds.statement:
[M23; research/openai_manuscript/Ambiently-homeomorphic-isolated-hypersurfaces-of-multiplicities-two-and-three-September-24-2026/build/sections/seeds.tex:116-128; proposition: The seeds] \label{seed:seeds}
There are real-coefficient weighted homogeneous polynomials
$p_1,p_2$, each in an even number $s_0$ of variables, such that:
\begin{enumerate}
\item both are sums, in disjoint variables, of chains with exponents
      at least $2$, and both have isolated critical points;
\item $\ord_0p_1=2$ and $\ord_0p_2=3$;
\item their spectral multisets are equal modulo $2$;
\item their real Seifert forms are isomorphic, and, separately, their
      integral monodromy modules are isomorphic;
\item both monodromy operators have order dividing $D=3^{12}$.
\end{enumerate}

